import {lessons,escapeHTML as esc} from './learning.js';
import {books,curriculum} from './curriculum.js';
import {labDefinitions} from './lab-science.js';
import {createNotebook} from './notebook.js';
export function createPages(api){
 let filter='all',noteTab='notes';const notebook=createNotebook({...api,lessons});
 const state=()=>api.getState();
 function renderTopics(){
  const s=state(),c=curriculum[s.grade],all=lessons.filter(l=>l.grade===s.grade);const list=all.filter(l=>filter==='all'||(filter==='interactive')===Boolean(l.activity||labDefinitions.some(d=>d.lesson===l.id)));
  document.querySelector('#book-select').value=s.book;
  document.querySelector('#curriculum-overview').innerHTML=`<article class="curriculum-card"><div class="curriculum-heading"><div><span class="eyebrow">HÀNH TRÌNH SINH HỌC ${s.grade}</span><h3>${c.name}</h3><p>${c.subtitle}</p></div><span class="curriculum-symbol">${api.icon(c.icon)}</span></div><ol class="curriculum-topics">${c.topics.map((t,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span>${t}</li>`).join('')}</ol><div class="curriculum-card-footer"><p>${c.extension}</p><button class="text-button" data-action="sources">Nguồn & bộ sách ${api.icon('external')}</button></div></article>`;
  document.querySelector('#lesson-count').textContent=`${list.length} / ${all.length} bài khám phá`;
  document.querySelector('#topic-grid').innerHTML=list.map((l,i)=>`<article class="topic-card ${i===0?'featured':''}"><div class="topic-image">${l.image?`<img src="assets/${l.image}" alt="${l.id==='cell'?'Mô hình tế bào thực vật':l.id==='dna'?'Mô hình ADN xoắn kép':'Hình ảnh thiên nhiên liên quan đến bài học'}" loading="lazy">`:`<div class="topic-illustration illustration-${l.visual}">${api.icon(l.icon)}</div>`}<span class="topic-type">${api.icon(l.icon)} ${l.type}</span><button class="bookmark-button ${s.saved.includes(l.id)?'saved':''}" data-action="bookmark" data-id="${l.id}" aria-label="${s.saved.includes(l.id)?'Bỏ lưu':'Lưu'} bài ${l.title}" aria-pressed="${s.saved.includes(l.id)}">${api.icon('bookmark')}</button>${s.completed.includes(l.id)?`<span class="lesson-done">${api.icon('check')} Đã khám phá</span>`:''}</div><div class="topic-body"><span class="topic-kicker">${l.kicker}</span><h3>${l.title}</h3><p>${l.description}</p><div class="topic-bottom"><span>${api.icon('clock')} ${l.minutes} phút</span><button data-action="lesson" data-id="${l.id}">Khám phá ${api.icon('arrow-up-right')}</button></div></div></article>`).join('')+(filter==='all'?`<article class="topic-card field-mission-card"><div class="topic-image"><img src="assets/forest.jpg" alt="Thiên nhiên để bắt đầu một nhiệm vụ quan sát" loading="lazy"><span class="topic-type">${api.icon('leaf')} Nhiệm vụ thực địa</span></div><div class="topic-body"><span class="topic-kicker">MANG KHOA HỌC RA NGOÀI</span><h3>${s.grade===10?'Nhìn chiếc lá, thấy tế bào':s.grade===11?'Theo dấu một mầm xanh':'Đa dạng ngay sân trường'}</h3><p>Quan sát, ghi lại điều chưa biết và đặt một câu hỏi có thể tìm hiểu thêm.</p><div class="topic-bottom"><span>${api.icon('sun')} Ngoài màn hình</span><button data-action="mission">Nhận nhiệm vụ ${api.icon('arrow-up-right')}</button></div></div></article>`:'');
  api.updateProgress();
 }
 function renderNotebook(tab=noteTab){noteTab=tab;notebook.render(tab)}
 function openNotebook(tab=noteTab){notebook.flush();api.closeDialog();api.navigate('notebook');renderNotebook(tab);api.updateProgress()}
 function enrichLesson(l){const s=state(),lab=labDefinitions.find(d=>d.lesson===l.id);if(lab&&!l.activity){document.querySelector('.lesson-callout').insertAdjacentHTML('afterend',`<button class="button button-dark" data-action="experiment" data-id="${lab.id}">${api.icon(lab.icon)} Thử trong phòng thí nghiệm</button>`)}const source=document.querySelector('.lesson-source');source.innerHTML=`Nguồn đọc thêm: <a href="${l.source}" target="_blank" rel="noopener">${l.source.includes('openstax.org')?'OpenStax Biology 2e':'Học liệu NXBGDVN'} ↗</a><br>Bộ sách tham khảo: <a href="${books[s.book].sources[l.grade]}" target="_blank" rel="noopener">${books[s.book].short} · Lớp ${l.grade} ↗</a>`}
 function openSources(){const s=state();api.showDialog('Khoa học cần có nguồn.','HỌC LIỆU / ĐỐI CHIẾU & ĐỌC THÊM',`<p class="dialog-lead">Các mạch kiến thức được tổ chức theo khối lớp, tham khảo cả Kết nối tri thức với cuộc sống và Chân trời sáng tạo. Bài viết và mô hình của VNScape là phần diễn giải riêng, không sao chép nguyên bộ sách.</p><div class="book-source-grid">${Object.entries(books).map(([key,b])=>`<article class="book-source-card"><span class="eyebrow">${key==='kntt'?'KẾT NỐI TRI THỨC':'CHÂN TRỜI SÁNG TẠO'}</span><h3>${b.name}</h3><p>Nguồn sách và thông tin của đơn vị xuất bản.</p>${[10,11,12].map(g=>`<a href="${b.sources[g]}" target="_blank" rel="noopener">Mở nguồn tham khảo lớp ${g} ↗</a>`).join('')}</article>`).join('')}</div><div class="teacher-note">Bản hiện tại đối chiếu theo mạch chủ đề; chưa phải bản ánh xạ đầy đủ từng bài, số trang và mọi phiên bản sách. Cần giáo viên rà soát trước khi dùng chính thức.</div><h3 class="source-section-title">Nguồn khoa học theo bài</h3><ul class="sources-list">${lessons.map(l=>`<li><a href="${l.source}" target="_blank" rel="noopener">Lớp ${l.grade} · ${l.title} ↗</a></li>`).join('')}</ul><details class="asset-credits"><summary>Hình ảnh, mô hình & phông chữ</summary><p>Ảnh thiên nhiên: Unsplash. Mô hình minh họa dựng bằng Three.js (MIT), dùng màu quy ước và không theo tỉ lệ. Phông Be Vietnam Pro và Lora từ Google Fonts được lưu cùng dự án.</p></details>`,'sources')}
 document.querySelector('#learning-filter').addEventListener('change',e=>{filter=e.target.value;renderTopics()});document.querySelector('#book-select').addEventListener('change',e=>{state().book=e.target.value==='ctst'?'ctst':'kntt';api.persist();renderTopics()});
 return {renderTopics,renderNotebook,openNotebook,enrichLesson,openSources,flushNotebook:()=>notebook.flush()};
}
